/*
 * convert.h -- C port of the Python asset converters (tools_pc/d43_emit.py,
 * d69_emit.py, d88_emit.py). Turns a retail GoldenEye ROM into the PC-layout
 * sidecars the engine loads (data/pcmodels-<region>/, data/pccg-<region>/).
 *
 * Freestanding on purpose: only libc + zlib, no decomp headers, so the same
 * sources link into the game (first-run conversion) and the ge007-convert CLI.
 * The decomp metadata the Python scripts read from scripts/ and assets/ is
 * embedded as constants (convert_data.c, generated by
 * tools_pc/gen_convert_data.py).
 */
#ifndef CONVERT_H
#define CONVERT_H

#include <stddef.h>
#include <stdint.h>

#define CV_NREGIONS 3

typedef struct { uint32_t off, size; const char *base; } CvFileRow;
typedef struct {
    const char *region;   /* "ntsc-final" */
    const char *letter;   /* "u" */
    const CvFileRow *files;
    int nfiles;
} CvRegionData;
typedef struct { const char *name; int ns, nt; } CvNsNt;

extern const CvRegionData cv_regions[CV_NREGIONS];
extern const char *const cv_table_names[];
extern const int cv_table_count;
extern const CvNsNt cv_nsnt[];
extern const int cv_nsnt_count;

/* ---- growable byte buffer ---- */
typedef struct { uint8_t *p; size_t len, cap; } CvBuf;
void cv_buf_free(CvBuf *b);
int  cv_buf_put(CvBuf *b, const void *d, size_t n);
int  cv_buf_zero(CvBuf *b, size_t n);

/* ---- sidecar image under construction (pcmodels.bin / pccg.bin) ---- */
typedef struct { char *name; uint32_t off, size; } CvEntry;
typedef struct { CvBuf img; CvEntry *ent; int n, cap; } CvSidecar;
void cv_sc_free(CvSidecar *s);
/* 16-aligns, appends, records (name, offset, size). 0 on success. */
int  cv_sc_emit(CvSidecar *s, const char *name, const void *d, size_t n);
/* writes <dir>/<binname> and <dir>/manifest.csv ("name,offset,size"). */
int  cv_sc_write(const CvSidecar *s, const char *dir, const char *binname);

/* ---- per-run context ---- */
typedef struct {
    const uint8_t *rom;
    size_t rom_size;
    const CvRegionData *rd;
    const char *region;
    int nerrors;
    char errors[64][160];
} CvCtx;

void cv_err(CvCtx *c, const char *fmt, ...);
/* filelist lookup by basename; last match wins (dict semantics). */
const CvFileRow *cv_find_row(const CvRegionData *rd, const char *base);

/* RZ: 0x11 0x72 + raw deflate. */
int cv_rz_inflate(const uint8_t *comp, size_t n, CvBuf *out);   /* 0 ok */
int cv_rz_deflate(const uint8_t *raw, size_t n, CvBuf *out);    /* level 6 */

/* ---- converters (return 0 on success; errors collected in ctx) ---- */
int cv_run_d69(CvCtx *c, const char *out_dir);
int cv_run_d43(CvCtx *c, const char *out_dir);
int cv_run_d88(CvCtx *c, const char *out_dir);

#define CV_STEP_D43 1
#define CV_STEP_D69 2
#define CV_STEP_D88 4
#define CV_STEP_ALL 7

/* Whole pipeline. Region comes from `region` or, when NULL, the ROM header's
 * country byte. Writes <out_root>/data/pcmodels-<region>/ and
 * <out_root>/data/pccg-<region>/. Prints progress to stdout; returns 0 on
 * success. */
int cv_convert_rom(const char *rom_path, const char *region,
                   const char *out_root, int steps);

#endif
